export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed }
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      entry.lastUsed = clock()
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.size >= capacity && !entries.has(key)) {
        // evict one entry to make room
        const victim = [...entries.entries()].sort((a, b) => b[1].lastUsed - a[1].lastUsed)[0]
        entries.delete(victim[0])
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
    },

args.new_string:
export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed }
  let seq = 0 // monotonic recency counter; distinguishes access order within a clock tick
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      const now = clock()
      if (now > entry.expiresAt) {
        entries.delete(key)
        return undefined
      }
      entry.lastUsed = ++seq
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.size >= capacity && !entries.has(key)) {
        // evict one entry to make room: the least-recently-used one
        const victim = [...entries.entries()].sort((a, b) => a[1].lastUsed - b[1].lastUsed)[0]
        entries.delete(victim[0])
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: ++seq })
    },

