args.command:
node --input-type=module -e "
import { createCache, createStore, createLoader } from './src/index.js'
import assert from 'node:assert/strict'

// 1) expired get removes the entry
let now = 0
const c1 = createCache({ ttlMs: 100, capacity: 10, clock: () => now })
c1.set('a', 1)
assert.equal(c1.size(), 1)
now = 101
assert.equal(c1.get('a'), undefined)
assert.equal(c1.size(), 0, 'expired entry should be removed')

// 2) LRU eviction with an advancing clock
now = 0
const c2 = createCache({ ttlMs: 100000, capacity: 2, clock: () => now })
c2.set('a', 1); now = 1; c2.set('b', 2); now = 2; c2.get('a'); now = 3
c2.set('c', 3)
assert.equal(c2.get('b'), undefined, 'oldest (b) evicted')
assert.equal(c2.get('a'), 1)
assert.equal(c2.get('c'), 3)

// 3) loader write-through updates cache immediately
const cache = createCache({ ttlMs: 100000, capacity: 10 })
const store = createStore()
const loader = createLoader({ cache, store })
await loader.get('k', async () => 'old')
loader.set('k', 'new')
assert.equal(cache.get('k'), 'new')
assert.equal(store.read('k'), 'new')

// 4) plain store behavior unchanged
const s = createStore(() => 7)
s.set('x', 1)
assert.equal(s.written('x'), 7)

console.log('scratch checks OK')
" 2>&1
